// Функція для автоматичного визначення API URL
export const getApiBaseUrl = (): string => {
  // Якщо запущено в розробці (localhost:3000)
  if (window.location.hostname === "localhost" || window.location.hostname === "127.0.0.1") {
    return "http://localhost:8000";
  }

  // Якщо запущено на Heroku або іншому продакшн сервері
  // Використовуємо той самий домен і протокол
  return `${window.location.protocol}//${window.location.host}`;
};

// Функція для WebSocket URL
export const getWebSocketUrl = (): string => {
  const apiUrl = getApiBaseUrl();
  return apiUrl.replace("http://", "ws://").replace("https://", "wss://");
};

// Константи для API
export const API_BASE_URL = getApiBaseUrl();
export const WS_BASE_URL = getWebSocketUrl();
